class RolePickerModal extends Modal {
  constructor(app, file) { super(app); this.file = file; }
  onOpen() {
    this.contentEl.empty();
    this.contentEl.createEl('h2', {text:'Mathsemble · 设置题卡默认教学角色'});
    this.contentEl.createEl('p', {text:'仅在此操作中更新正式 role 字段并清理旧 teaching_role；导出不会改动原文件。'});
    const choices = this.contentEl.createDiv({cls:'mwb-role-picker'});
    for (const role of [{id:'例题',label:'例题'},{id:'变式',label:'变式'},{id:'训练',label:'训练'},{id:null,label:'清除角色（未标注）'}]) {
      const button = choices.createEl('button', {text:role.label});
      button.onclick = async () => {
        button.disabled = true;
        try {
          await this.app.fileManager.processFrontMatter(this.file, fm => {
            if (role.id === null) delete fm.role;
            else fm.role = role.id === 'assessment' ? 'test' : role.id;
            delete fm.teaching_role;
          });
          new Notice(`教学角色已设置为：${role.id === null ? '未标注' : role.label}`);
          this.close();
        } catch (e) { new Notice('写入教学角色失败：'+(e?.message || e)); button.disabled = false; }
      };
    }
  }
  onClose() { this.contentEl.empty(); }
}

class PreviewModal extends Modal {
  static uiId = 0;
  constructor(app, plugin, file, markdown, exam = null, opts = {}) {
    super(app);
    this.plugin = plugin;
    this.sourceScope = opts.sourceScope || mwbSourceScope(file, !!exam);
    this.sourceSnapshot = opts.sourceSnapshot || null;
    const current = mwbSourceRecord(file, markdown);
    this.file = current.file;
    this.markdown = markdown;
    this.sourceMetadata = current.metadata;
    this.exam = exam ? {...exam, items:exam.items.map(item => {
      const frozen = mwbSourceRecord(item.file, item.markdown);
      return {...item, file:frozen.file, metadata:frozen.metadata};
    })} : null;
    if (!this.sourceSnapshot && typeof app?.vault?.read === 'function' &&
        typeof app.vault.getAbstractFileByPath === 'function') {
      const records = exam ? exam.items : [{file,markdown}];
      this.sourceSnapshot = {path:mwbSourceScopePath(this.sourceScope), entries:records.map(item =>
        ({live:item.file,record:mwbSourceRecord(item.file,item.markdown)}))};
    }
    this.sourceDirty = false;
    this.sourceRevision = 0;
    this.sourceReadJob = null;
    this.sourceWatchStop = null;
    this.documentMode = !!opts.documentMode;
    this.metaSelections = {student:[...MODE_DEFAULTS.student], teacher:[...MODE_DEFAULTS.teacher]};
    this.metaPosition = 'below';
    this.examTitle = exam?.title || file.basename;
    this.mode = this.documentMode ? 'document' : 'student';
    this.documentRenderSource = null;
    this.ready = false;
    this.exportJob = null;
    this.closed = false;
    this.generation = 0;
    this.spaceSettings = { ...DEFAULT_SPACE_SETTINGS };
    this.solutionOptions = { solutionSpaces: false, showSolution: true };
    this.renderQueue = Promise.resolve();
    this.renderOwner = null;
    this.renderController = null;
    this.renderBusy = false;
    this.measureOwner = null;
    this.measureParent = null;
    this.solutionHeights = [];
    this.spaceDiagnostics = [];
    this.measurePage = null;
    this.renderWarnings = [];
    this.partialExportApproved = false;
    this.lastSavedPdfPath = null;
    this.previewPages = null;
    this.previewPaginationReport = null;
    this.questionPlan = null;
    this.showQuestionBounds = false;
  }

  startSourceWatch() {
    this.sourceWatchStop?.();
    const oldOwner = this.sourceWatchOwner;
    this.sourceWatchOwner = null;
    mwbReleaseRenderOwner(this.plugin, oldOwner);
    this.sourceWatchStop = null;
    if (this.sourceSnapshot) {
      this.sourceWatchStop = mwbWatchSource(this.app.vault, this.sourceScope, (kind,file,oldPath) => {
        if (this.closed) return;
        this.markSourceChanged('源文件已变化（' + kind + '）：' + (oldPath || file?.path || ''));
      });
    }
    if (this.sourceWatchStop) {
      const owner = this.sourceWatchOwner = mwbCreateRenderOwner(this.plugin);
      const stop = this.sourceWatchStop;
      if (owner !== this.plugin) owner?.register?.(() => {
        stop();
        if (!this.closed && this.sourceWatchOwner === owner) {
          this.cancelSourceRead('Mathsemble 已停用');
          this.cancelPreview('Mathsemble 已停用');
          this.cancelExport('Mathsemble 已停用');
          this.ready = false;
          this.updateSourceStatus('Mathsemble 已停用，请关闭预览窗口。');
          this.closed = true;
        }
      });
    }
    if (this.readSourceButton) this.readSourceButton.disabled = !this.sourceSnapshot;
    this.updateSourceStatus();
  }

  updateSourceStatus(message) {
    if (this.closed || !this.sourceStatus) return;
    if (!this.sourceSnapshot) { this.sourceStatus.style.display = 'none'; if (this.sourcePromptButton) this.sourcePromptButton.style.display = 'none'; return; }
    const attention = !!(this.sourceDirty || this.sourceReadJob || message);
    this.sourceStatus.style.display = attention ? '' : 'none';
    this.sourceStatus.setAttribute?.('data-stale', String(!!this.sourceDirty));
    this.sourceStatus.setText(message || (this.sourceDirty
      ? '源文件已变化；当前为旧快照，暂停 PDF／HTML 输出。请保存修改后点击“读取最新内容”。'
      : `当前快照包含 ${this.sourceSnapshot.entries.length} 份已保存 Markdown；“重新预览”仅重排此快照，未保存的编辑不在其中。`));
    if (this.sourcePromptButton) {
      this.sourcePromptButton.style.display = (this.sourceDirty || this.sourceReadJob) ? '' : 'none';
      this.sourcePromptButton.setText(this.sourceReadJob ? '取消读取' : '读取最新内容');
    }
    this.updateCompactStatus();
  }

  markSourceChanged(message) {
    this.sourceDirty = true;
    this.sourceRevision = (this.sourceRevision || 0) + 1;
    this.cancelExport('源文件发生变化，旧导出已取消');
    if (!this.closed) {
      this.setExportBusy(!!this.exportJob);
      this.updateSourceStatus((message || '源文件已变化') + '。当前快照未自动替换；请读取最新内容后再输出。');
    }
  }

  cancelSourceRead(message = '读取已取消，旧快照未替换') {
    if (this.sourceReadJob && !this.sourceReadJob.controller.signal.aborted)
      this.sourceReadJob.controller.abort(mwbExportAbortError(message));
  }

  async reloadSource() {
    if (this.closed || !this.sourceSnapshot) return false;
    if (this.sourceReadJob) { new Notice('正在读取源文件，请完成或取消后再操作'); return false; }
    this.cancelPreview('正在读取最新内容，旧预览已取消');
    this.cancelExport('正在读取最新内容，旧导出已取消');
    const job = {controller:new AbortController(), generation:++this.generation, sourceRevision:this.sourceRevision};
    this.sourceReadJob = job;
    this.ready = false;
    if (this.readSourceButton) this.readSourceButton.setText('取消读取');
    this.setExportBusy(!!this.exportJob);
    this.updateSourceStatus('正在读取并复核已保存的源文；完成前不替换当前快照…');
    try {
      const snapshot = await mwbReadSourceSnapshot(this.app.vault, this.sourceScope, {signal:job.controller.signal});
      mwbThrowIfExportAborted(job.controller.signal);
      if (this.closed || this.sourceReadJob !== job || this.generation !== job.generation)
        throw mwbExportAbortError('预览状态已变化，旧读取结果已丢弃');
      if (this.sourceRevision !== job.sourceRevision)
        throw mwbSourceError('读取完成时源文再次发生变化；旧快照未替换，请重试');
      // Prepare the COMPLETE new exam before touching any current state. A bad
      // file, empty exam or quota failure leaves the old batch intact.
      let exam = null;
      if (this.exam) {
        exam = collectExamItems(snapshot.entries.map(entry => entry.record), {groupBy:this.exam.groupBy || 'question_type'});
        if (!exam.items.length) throw new Error('文件夹中没有有效题卡；原组卷快照未替换');
        if (exam.items.length > 100) throw new Error('一次组卷至多 100 道题；原组卷快照未替换');
      }
      const record = exam ? exam.items[0] : snapshot.entries[0]?.record;
      if (!record) throw new Error('源文件为空，快照未替换');
      this.sourceSnapshot = snapshot;
      this.sourceScope.path = snapshot.path;
      this.file = record.file;
      this.sourceMetadata = record.metadata;
      if (exam) this.exam = {...exam, title:this.examTitle};
      else this.markdown = record.markdown;
      this.sourceDirty = false;
      this.sourceRevision++;
      this.sourceReadJob = null; // renderMode must not abort this committed read.
      this.lastSavedPdfPath = null;
      if (this.openPdfButton) this.openPdfButton.style.display = 'none';
      if (this.readSourceButton) this.readSourceButton.setText('读取最新内容');
      this.setExportBusy(!!this.exportJob);
      this.updateSourceStatus();
      await this.renderMode(this.mode); // Same mode/preferences, new text snapshot.
      return true;
    } catch (error) {
      if (!this.closed && this.sourceReadJob === job) {
        if (error?.name !== 'AbortError') this.markSourceChanged('读取未完成：' + (error?.message || error));
        this.updateSourceStatus((error?.message || String(error)) + '；旧快照保留，未写入源文件。');
      }
      return false;
    } finally {
      if (this.sourceReadJob === job) {
        this.sourceReadJob = null;
        if (!this.closed) {
          if (this.readSourceButton) this.readSourceButton.setText('读取最新内容');
          this.setExportBusy(!!this.exportJob);
        }
      }
    }
  }

  async assertSourceCurrent(signal) {
    if (!this.sourceSnapshot) return; // Isolated host fixtures have no Vault.
    if (this.sourceDirty || this.sourceReadJob)
      throw mwbSourceError('当前预览不是最新源文，请先读取最新内容');
    const snapshot = this.sourceSnapshot, revision = this.sourceRevision;
    try {
      const current = await mwbReadSourceSnapshot(this.app.vault, this.sourceScope, {signal});
      mwbThrowIfExportAborted(signal);
      if (this.closed || snapshot !== this.sourceSnapshot || revision !== this.sourceRevision ||
          this.sourceDirty || !mwbSameSourceSnapshot(snapshot,current))
        throw mwbSourceError('源文件内容、路径或组卷文件列表已变化；请读取最新内容后再输出');
    } catch (error) {
      if (error?.name !== 'AbortError' && snapshot === this.sourceSnapshot && !this.closed)
        this.markSourceChanged(error?.message || '无法确认源文是否仍然有效');
      throw error;
    }
  }

  addRenderWarnings(stage, issues) {
    // Rechecking the same rendered question must not revoke an existing
    // acknowledgement. Keep the stage/path and issue location in the key so
    // the same failure in a different question still requires fresh consent.
    const known = new Set(this.renderWarnings);
    for (const issue of issues || []) {
      const warning = `${stage}：${issue}`;
      if (known.has(warning)) continue;
      known.add(warning);
      this.renderWarnings.push(warning);
    }
  }

  assertPartialExportApproved() {
    if (this.renderWarnings.length && !this.partialExportApproved) {
      throw new Error('存在局部渲染失败：请查看警告并勾选“允许不完整的 PDF”，然后继续导出。');
    }
  }

  onOpen() {
    this.closed = false;
    this.modalEl.addClass('mwb-modal');
    this.contentEl.empty();
    this.contentEl.createEl('h2', { text: this.documentMode ? 'Mathsemble · Markdown 文档 A4 预览（实验版）' : this.exam ? 'Mathsemble · 数学试卷 A4 预览' : 'Mathsemble · 数学题卡 A4 预览' });
    const controls = this.contentEl.createDiv({ cls: 'mwb-controls' });
    const modeControls = controls.createDiv({cls:'mwb-mode-controls'});
    const primaryControls = controls.createDiv({cls:'mwb-primary-controls'});
    const secondaryControls = controls.createDiv({cls:'mwb-secondary-controls'});
    const settingsMenu = secondaryControls.createEl('details', {cls:'mwb-toolbar-menu mwb-settings-menu'});
    settingsMenu.createEl('summary', {text:'设置'});
    const settingsControls = settingsMenu.createDiv({cls:'mwb-menu-panel'});
    const moreMenu = secondaryControls.createEl('details', {cls:'mwb-toolbar-menu mwb-more-menu'});
    moreMenu.createEl('summary', {text:'更多 ···'});
    const moreControls = moreMenu.createDiv({cls:'mwb-menu-panel'});
    settingsMenu.addEventListener('toggle', () => {if (settingsMenu.open) moreMenu.open = false;});
    moreMenu.addEventListener('toggle', () => {if (moreMenu.open) settingsMenu.open = false;});
    const student = modeControls.createEl('button', { text: this.documentMode ? '讲义学生版' : '学生卷' });
    const teacher = modeControls.createEl('button', { text: this.documentMode ? '讲义教师版' : '教师卷' });
    const originalDocument = this.documentMode ? modeControls.createEl('button', { text: '原文预览（不转换答案）' }) : null;
    this.modeButtons = {student,teacher,document:originalDocument};
    this.refreshPreviewButton = moreControls.createEl('button', {text:'重新预览'});
    this.refreshPreviewButton.title = '按当前快照重新排版，不重新读取文件；读取源文修改请使用“读取最新内容”';
    this.refreshPreviewButton.onclick = () => {
      moreMenu.open = false;
      if (this.renderBusy) this.cancelPreview();
      else void this.renderMode(this.mode);
    };
    this.readSourceButton = moreControls.createEl('button', {text:'读取最新内容'});
    this.readSourceButton.title = '重新读取已保存的源文件；整卷重新扫描当前文件夹，不递归。成功后整体替换快照';
    this.readSourceButton.onclick = () => {
      moreMenu.open = false;
      if (this.sourceReadJob) this.cancelSourceRead('用户取消读取，旧快照未替换');
      else void this.reloadSource();
    };
    this.sourceStatus = this.contentEl.createDiv({cls:'mwb-source-status'});
    this.sourceStatus.setAttribute?.('role','status');
    this.sourceStatus.setAttribute?.('aria-live','polite');
    this.sourcePromptButton = this.contentEl.createEl('button', {cls:'mwb-source-action', text:'读取最新内容'});
    this.sourcePromptButton.onclick = () => this.readSourceButton.click();
    this.startSourceWatch();
    const print = primaryControls.createEl('button', { text: '保存 PDF' });
    const openPdfButton = moreControls.createEl('button', { text: '打开已保存 PDF' });
    openPdfButton.style.display = 'none';
    this.openPdfButton = openPdfButton;
    openPdfButton.title = '使用操作系统默认 PDF 阅读器打开上次成功保存的文件';
    openPdfButton.onclick = async () => {
      moreMenu.open = false;
      if (!this.lastSavedPdfPath) return;
      try {
        await openExportedPdf(this.app, this.lastSavedPdfPath);
      } catch (error) {
        new Notice('打开 PDF 失败：' + (error?.message || error), 10000);
      }
    };
    const dual = primaryControls.createEl('button', {cls:'mwb-primary-export', text: '导出学生版＋教师版 PDF' });
    dual.title = '按同一源文快照和设置分别生成两版；全部生成成功后再保存，不调用系统打印';

    const ratioLabel = settingsControls.createEl('label', { cls: 'mwb-setting-label', text: '等高留白' });
    const ratioInput = ratioLabel.createEl('select', { cls: 'mwb-setting-select', attr: { 'aria-label': '教师专用块高度比例' } });
    for (const amount of [50, 75, 90, 100, 110, 125, 150]) {
      const option = ratioInput.createEl('option', { text: `${amount}%`, value: String(amount) });
      option.value = String(amount);
      if (amount === 100) option.selected = true;
    }
    const minimumLabel = settingsControls.createEl('label', { cls: 'mwb-setting-label', text: '最小' });
    const minimumInput = minimumLabel.createEl('select', { cls: 'mwb-setting-select', attr: { 'aria-label': '最小留白高度' } });
    for (const amount of [0, 2, 4]) {
      const option = minimumInput.createEl('option', { text: `${amount} cm`, value: String(amount) });
      option.value = String(amount);
      if (amount === this.spaceSettings.minimumCm) option.selected = true;
    }
    // Both options are presentation-only; never rewrite the source note.
    const studentSolutionLabel = settingsControls.createEl('label', { cls: 'mwb-setting-label', text: 'solution 留白 ' });
    const studentSolutionCheckbox = studentSolutionLabel.createEl('input', { type: 'checkbox' });
    studentSolutionCheckbox.checked = this.solutionOptions.solutionSpaces;
    studentSolutionCheckbox.setAttribute('aria-label', '学生版为 solution 预留答题空白');
    studentSolutionCheckbox.onchange = () => {
      this.solutionOptions.solutionSpaces = !!studentSolutionCheckbox.checked;
      if (this.mode === 'student') void this.renderMode('student');
    };
    const teacherSolutionLabel = settingsControls.createEl('label', { cls: 'mwb-setting-label', text: '显示 solution ' });
    const teacherSolutionCheckbox = teacherSolutionLabel.createEl('input', { type: 'checkbox' });
    teacherSolutionCheckbox.checked = this.solutionOptions.showSolution;
    teacherSolutionCheckbox.setAttribute('aria-label', '教师版显示 solution 解题思路');
    teacherSolutionCheckbox.onchange = () => {
      this.solutionOptions.showSolution = !!teacherSolutionCheckbox.checked;
      if (this.mode === 'teacher') void this.renderMode('teacher');
    };
    this.solutionModeLabels = { student: studentSolutionLabel, teacher: teacherSolutionLabel };
    if (this.documentMode) { ratioLabel.style.display = ''; minimumLabel.style.display = ''; }
    if (this.exam) {
      const groupingLabel = settingsControls.createEl('label', {cls:'mwb-setting-label', text:'分组依据'});
      const groupingSelect = groupingLabel.createEl('select', {cls:'mwb-setting-select', attr:{'aria-label':'分组依据'}});
      for (const mode of GROUPING_MODES) {
        groupingSelect.createEl('option', {text:mode.label, value:mode.id});
      }
      groupingSelect.value = this.exam.groupBy || 'question_type';
      groupingSelect.addEventListener('change', () => {
        this.exam = collectExamItems(this.exam.items, {groupBy:groupingSelect.value});
        void this.renderMode(this.mode);
      });
      const titleInput = settingsControls.createEl('input', {cls:'mwb-exam-title-input', type:'text', attr:{'aria-label':'试卷标题', 'placeholder':'试卷标题'}});
      titleInput.value = this.examTitle;
      titleInput.addEventListener('change', () => {
        this.examTitle = titleInput.value.trim().slice(0, 100) || '数学试卷';
        void this.renderMode(this.mode);
      });
    }
    if (!this.documentMode) {
      const selector = settingsControls.createDiv({cls:'mwb-meta-selector'});
      selector.createEl('strong',{text:'导出元信息（仅所选字段；学生/教师独立）'});
      const group = selector.createDiv({cls:'mwb-meta-fields'});
      this.metaCheckboxes = new Map();
      for (const field of META_FIELDS) {
        const label = group.createEl('label');
        const checkbox = label.createEl('input',{type:'checkbox'});
        checkbox.checked = this.metaSelections[this.mode].includes(field.key);
        checkbox.addEventListener('change',()=>{
          const values = new Set(this.metaSelections[this.mode]);
          if (checkbox.checked) values.add(field.key); else values.delete(field.key);
          this.metaSelections[this.mode] = [...values];
          void this.renderMode(this.mode);
        });
        label.appendText(field.label);
        this.metaCheckboxes.set(field.key,checkbox);
      }
      const placement = selector.createEl('label',{text:'显示位置 '});
      const select = placement.createEl('select');
      for (const choice of [{key:'above',label:'题干前'}, {key:'below',label:'首段题干后'}, {key:'end',label:'题末'}]) {
        select.createEl('option',{value:choice.key,text:choice.label});
      }
      select.value = this.metaPosition;
      select.addEventListener('change',()=>{this.metaPosition=select.value; void this.renderMode(this.mode);});
    }
    // Diagnose only on demand. The panel moves beside the A4 scroll area
    // after construction; it never becomes part of rendered/PDF source DOM.
    this.diagnosticsPanel = this.contentEl.createDiv({cls:'mwb-diagnostics'});
    this.diagnosticsPanel.id = 'mwb-diagnostics-' + (++PreviewModal.uiId);
    this.diagnosticsPanel.setAttribute('role','region');
    this.diagnosticsPanel.setAttribute('aria-label','预览诊断');
    this.diagnosticsPanel.setAttribute('aria-hidden','true');
    this.diagnosticsPanel.style.display = 'none';
    this.diagnosticsPanel.addEventListener('keydown', event => {
      if (event.key === 'Escape') { this.toggleDiagnostics(false); this.diagnosticsToggleButton?.focus?.(); }
    });
    const diagnosticHeader = this.diagnosticsPanel.createDiv({cls:'mwb-diagnostics-header'});
    diagnosticHeader.createEl('strong',{text:'预览诊断'});
    const diagnosticClose = diagnosticHeader.createEl('button',{text:'关闭'});
    diagnosticClose.setAttribute('aria-label','关闭预览诊断');
    diagnosticClose.onclick = () => this.toggleDiagnostics(false);
    const diagnosticTabs = this.diagnosticsPanel.createDiv({cls:'mwb-diagnostics-tabs'});
    this.diagnosticTabs = {};
    this.diagnosticSections = {};
    const tabLabels = {blocks:'块结构',spaces:'留白',resources:'资源'};
    for (const [key,label] of Object.entries(tabLabels)) {
      const tab = diagnosticTabs.createEl('button',{text:label});
      tab.setAttribute('type','button');
      tab.onclick = () => this.selectDiagnosticsTab(key);
      this.diagnosticTabs[key] = tab;
      this.diagnosticSections[key] = this.diagnosticsPanel.createDiv({cls:'mwb-diagnostics-section'});
    }
    const diagnosticBlocks = this.diagnosticSections.blocks;
    const diagnosticSpaces = this.diagnosticSections.spaces;
    const diagnosticResources = this.diagnosticSections.resources;
    this.diagnosticSpaceSummary = diagnosticSpaces.createDiv({cls:'mwb-diagnostic-summary'});
    this.diagnosticSpaceDetails = diagnosticSpaces.createDiv({cls:'mwb-diagnostic-details'});
    this.diagnosticResourceSummary = diagnosticResources.createDiv({cls:'mwb-diagnostic-summary'});
    this.diagnosticResourceDetails = diagnosticResources.createDiv({cls:'mwb-diagnostic-details'});
    this.diagnosticActiveTab = 'blocks';
    this.selectDiagnosticsTab('blocks');
    const boundsLabel=diagnosticBlocks.createEl('label', {cls:'mwb-setting-label',text:'显示块范围 '});
    const boundsInput=boundsLabel.createEl('input',{type:'checkbox'});
    boundsInput.checked=false;
    boundsInput.onchange=()=>{this.showQuestionBounds=!!boundsInput.checked;this.updateQuestionBounds();};
    const copyQuestions=diagnosticBlocks.createEl('button',{text:'复制块边界'});
    copyQuestions.onclick=async()=>{
      const report={policy:'strict-h5',file:this.file?.path || '',
        blocks:this.questionPlan?.groups || [],questions:this.questionPlan?.groups || [],warnings:this.questionPlan?.warnings || [],
        pagination:this.previewPaginationReport?.strictQuestionPages || []};
      try {await navigator.clipboard.writeText(JSON.stringify(report,null,2));new Notice('块边界和分页核验已复制');}
      catch(_){new Notice('无法复制，请查看块范围说明');}
    };
    this.questionBoundaryPanel=diagnosticBlocks.createDiv({cls:'mwb-question-boundary-report'});
    const html = moreControls.createEl('button', { text: '保存 HTML 备用' });
    this.exportButtons = [print, dual, html];
    this.cancelExportButton = primaryControls.createEl('button', {text:'取消导出'});
    this.cancelExportButton.style.display = 'none';
    this.cancelExportButton.title = '取消尚未完成的导出；已开始的文件写入不能撤回，已保存文件会保留';
    this.cancelExportButton.onclick = () => this.cancelExport('用户取消导出');
    this.status = diagnosticResources.createDiv({ cls: 'mwb-status', text: '渲染中…' });
    this.dualReportEl = this.contentEl.createDiv({cls:'mwb-dual-report'});
    this.dualReportEl.setAttribute('role', 'status');
    this.dualReportEl.style.display = 'none';
    const errorActions = diagnosticResources.createDiv({ cls: 'mwb-error-actions' });
    const copyErrorButton = errorActions.createEl('button', { text: '复制渲染错误详情' });
    copyErrorButton.style.display = 'none';
    this.copyErrorButton = copyErrorButton;
    copyErrorButton.onclick = async () => {
      if (!this.lastRenderError) return;
      try {
        await navigator.clipboard.writeText(this.lastRenderError);
        new Notice('渲染错误详情已复制');
      } catch (_) {
        new Notice('无法自动复制；请选中预览窗口中的错误文字复制。');
      }
    };
    this.riskBanner = this.contentEl.createDiv({cls:'mwb-risk-banner'});
    this.riskBanner.style.display = 'none';
    this.riskBanner.setAttribute('role','alert');
    this.riskMessage = this.riskBanner.createEl('span');
    const riskAction = this.riskBanner.createEl('button',{text:'查看详情'});
    riskAction.onclick = () => this.toggleDiagnostics(true,'resources');
    const partialWarning = this.contentEl.createDiv({ cls: 'mwb-partial-warning' });
    partialWarning.style.display = 'none';
    const partialLabel = partialWarning.createEl('label');
    const partialCheckbox = partialLabel.createEl('input', { type: 'checkbox' });
    partialLabel.appendText(' 已了解局部公式或图片可能缺失，允许导出不完整的 PDF / HTML（仅当前版）');
    partialCheckbox.onchange = () => {
      this.partialExportApproved = !!partialCheckbox.checked;
      if (!this.partialExportApproved) this.cancelExport('已撤销不完整输出许可，导出已取消');
    };
    this.partialWarning = partialWarning;
    this.partialCheckbox = partialCheckbox;
    this.overflowWarning = this.contentEl.createDiv({cls:'mwb-partial-warning'});
    this.overflowWarning.style.display = 'none';
    const overflowLabel = this.overflowWarning.createEl('label');
    this.overflowCheckbox = overflowLabel.createEl('input', {type:'checkbox'});
    overflowLabel.appendText(' 仅打印正常内容：跳过超出 A4 的独立公式、表格和图片，并在原位标记（仅当前版 PDF）');
    this.overflowCheckbox.onchange = () => {
      this.cancelExport('容错打印设置已变化，导出已取消');
      this.overflowOmissionEnabled = !!this.overflowCheckbox.checked;
      try {
        const report = this.showPaginatedPreview();
        this.previewPaginationIssue = '';
        this.status.setText(`A4 预览 ${report.pages} 页；已跳过 ${report.omittedBlocks.length} 处超出页面的内容，原文保留。`);
      } catch (error) {
        this.clearPaginatedPreview();
        this.previewPaginationIssue = String(error?.message || error).slice(0,1000);
        this.status.setText('A4 分页预览失败，当前显示连续内容：' + this.previewPaginationIssue);
      }
      this.updateCompactStatus();
    };
    const copyMetadata = diagnosticBlocks.createEl('button', {text:'复制元信息检查'});
    if (this.documentMode) copyMetadata.style.display='none';
    copyMetadata.title = '列出题卡中缺失的正式字段和字段冲突；不会自动补造事实或修改文件';
    copyMetadata.onclick = async () => {
      const records = this.exam ? this.exam.items : [{file:this.file, markdown:this.markdown, metadata:this.sourceMetadata}];
      const rows = records.map(item => ({
        文件:item.file?.path || '',
        题目ID:metadataOf(item).id || '',
        缺少字段:metadataAudit(metadataOf(item)).missing,
        待复核:metadataAudit(metadataOf(item)).warnings,
      }));
      try { await navigator.clipboard.writeText(JSON.stringify(rows,null,2)); new Notice('题卡元信息检查结果已复制'); }
      catch (_) { new Notice('无法复制元信息检查报告'); }
    };
    const copySpaces = diagnosticSpaces.createEl('button', {text:'复制留白核验'});
    copySpaces.title = '复制学生版实际渲染高度与原解答高度的逐块对照（包括长 Markdown 讲义）';
    copySpaces.onclick = async () => {
      if (!this.ready || this.mode !== 'student' || !this.spaceDiagnostics.length) {
        new Notice('请先完成含解答块的学生版渲染'); return;
      }
      const rows = this.spaceDiagnostics.map((r,i)=>({
        题号:r.question || i+1, 文件:r.source || (this.file?.path || ''),
        教师块像素:Number(r.teacherPx.toFixed(2)), 目标留白像素:Number(r.targetPx.toFixed(2)),
        预览实测像素:Number(r.actualPx.toFixed(2)), 偏差像素:Number(r.deltaPx.toFixed(2)),
        比例:r.ratio
      }));
      try { await navigator.clipboard.writeText(JSON.stringify(rows,null,2)); new Notice('留白高度核验数据已复制'); }
      catch (_) { new Notice('无法复制留白报告；请检查系统剪贴板权限'); }
    };
    // A compact, always-visible summary replaces the long technical report.
    // This workspace contains only previews and UI; exported PDFs clone
    // this.rendered, never these sibling controls or diagnostics.
    const workspace = this.contentEl.createDiv({cls:'mwb-preview-workspace'});
    const scroll = workspace.createDiv({ cls: 'mwb-scroll' });
    workspace.appendChild(this.diagnosticsPanel);
    const footer = this.contentEl.createDiv({cls:'mwb-preview-footer'});
    this.compactStatus = footer.createDiv({cls:'mwb-compact-status', text:'正在准备预览…'});
    this.compactStatus.setAttribute('role','status');
    this.compactStatus.setAttribute('aria-live','polite');
    this.diagnosticsToggleButton = footer.createEl('button', {cls:'mwb-diagnostics-toggle',text:'查看诊断'});
    this.diagnosticsToggleButton.setAttribute('aria-controls',this.diagnosticsPanel.id);
    this.diagnosticsToggleButton.setAttribute('aria-expanded','false');
    this.diagnosticsToggleButton.onclick = () => this.toggleDiagnostics();
    this.quickCancelPreviewButton = footer.createEl('button', {cls:'mwb-quick-cancel',text:'取消预览'});
    this.quickCancelPreviewButton.style.display = 'none';
    this.quickCancelPreviewButton.onclick = () => this.cancelPreview();
    this.page = scroll.createDiv({ cls: 'mwb-page' });
    this.rendered = this.page.createDiv({ cls: 'mwb-typography mwb-print-document' });
    ratioInput.onchange = () => { this.spaceSettings.ratio = Number(ratioInput.value); if (this.mode === 'student') void this.renderMode('student'); };
    minimumInput.onchange = () => { this.spaceSettings.minimumCm = Number(minimumInput.value); if (this.mode === 'student') void this.renderMode('student'); };
    student.onclick = () => { void this.renderMode('student'); };
    teacher.onclick = () => { void this.renderMode('teacher'); };
    if (originalDocument) originalDocument.onclick = () => { void this.renderMode('document'); };
    print.onclick = () => { void this.exportPdf({save:true, printAfter:false}); };
    dual.onclick = () => { void this.exportBothPdf(); };
    html.onclick = () => { moreMenu.open = false; void this.saveHtml(); };
    void this.renderMode(this.mode);
  }


  toggleDiagnostics(force, tab) {
    if (!this.diagnosticsPanel) return;
    const open = force === undefined ? this.diagnosticsPanel.style.display === 'none' : !!force;
    this.diagnosticsPanel.style.display = open ? '' : 'none';
    this.diagnosticsPanel.setAttribute('aria-hidden',String(!open));
    if (this.diagnosticsToggleButton) {
      this.diagnosticsToggleButton.setAttribute('aria-expanded',String(open));
      this.diagnosticsToggleButton.setText(open ? '关闭诊断' : '查看诊断');
    }
    if (open) {
      this.selectDiagnosticsTab(tab || this.diagnosticActiveTab || 'blocks');
      this.updateDiagnostics();
    }
  }

  selectDiagnosticsTab(key) {
    if (!this.diagnosticSections?.[key]) return;
    this.diagnosticActiveTab = key;
    for (const [id,node] of Object.entries(this.diagnosticSections)) {
      node.style.display = id === key ? '' : 'none';
      const tab = this.diagnosticTabs?.[id];
      if (tab) tab.setAttribute('aria-pressed',String(id === key));
    }
  }

  updateDiagnostics() {
    if (this.diagnosticSpaceSummary) {
      const rows = this.spaceDiagnostics || [];
      const total = rows.reduce((sum,r) => sum + (Number(r.targetPx) || 0),0);
      this.diagnosticSpaceSummary.setText(`${rows.length} 处留白核验 · 目标总高度 ${total.toFixed(1)} px`);
      if (this.diagnosticSpaceDetails) this.diagnosticSpaceDetails.setText(rows.length
        ? rows.map((r,i)=>`块${r.question || i+1} · 目标 ${Number(r.targetPx||0).toFixed(1)} px · 实际 ${Number(r.actualPx||0).toFixed(1)} px · 偏差 ${Number(r.deltaPx||0).toFixed(1)} px`).join('\n')
        : '当前模式没有可显示的学生留白核验；请切换至学生版。');
    }
    if (this.diagnosticResourceSummary) {
      const root = this.rendered;
      const images = root?.querySelectorAll?.('img')?.length || 0;
      const formulae = root?.querySelectorAll?.('mjx-container')?.length || 0;
      const warnings = this.renderWarnings || [];
      const omitted = this.previewPaginationReport?.omittedBlocks || [];
      this.diagnosticResourceSummary.setText(`图片 ${images} · MathJax 容器 ${formulae} · 渲染警告 ${warnings.length}`);
      const details = [...warnings, ...omitted.map(item => `已跳过${item.type} ${item.index}：${item.summary}`)];
      if (this.previewPaginationIssue) details.push(this.previewPaginationIssue);
      if (this.diagnosticResourceDetails) this.diagnosticResourceDetails.setText(details.length
        ? details.join('\n') : '未记录局部渲染警告；资源是否完整仍以导出前复检为准。');
    }
  }

  updateCompactStatus() {
    if (!this.compactStatus || this.closed) return;
    const bits = [];
    const blocks = this.questionPlan?.groups?.length;
    if (this.documentMode) bits.push(`${blocks ?? 0} 块`);
    else if (this.exam) bits.push(`${this.exam.items.length} 题卡`);
    else bits.push('单题卡');
    if (this.mode === 'student') bits.push(`${this.spaceDiagnostics?.length || 0} 处留白核验`);
    if (!this.renderBusy && this.previewPaginationReport?.pages) bits.push(`A4 ${this.previewPaginationReport.pages} 页`);
    const bounds = this.questionPlan?.warnings?.length || 0;
    if (bounds) bits.push(`${bounds} 项块边界提示`);
    const warnings = this.renderWarnings?.length || 0;
    const omitted = this.previewPaginationReport?.omittedBlocks?.length || 0;
    if (omitted) bits.push(`已跳过 ${omitted} 处内容`);
    if (warnings) bits.push(`${warnings} 项渲染警告`);
    if (this.sourceDirty) bits.unshift('源文已变化');
    else if (this.sourceReadJob) bits.unshift('正在读取源文');
    else if (this.renderBusy) bits.unshift('正在渲染');
    else if (this.exportJob) bits.unshift(this.exportJob.controller?.signal?.aborted ? '正在取消导出' :
      this.exportJob.kind === 'dual' ? '正在导出双版 PDF' : '正在导出');
    else if (this.lastRenderError && !this.ready) bits.unshift('渲染失败');
    else if (this.previewPaginationIssue) bits.unshift('A4 分页预览失败');
    this.compactStatus.setText(bits.join(' · '));
    if (this.quickCancelPreviewButton) this.quickCancelPreviewButton.style.display = this.renderBusy ? '' : 'none';
    if (this.modeButtons) for (const [mode,button] of Object.entries(this.modeButtons)) {
      if (!button) continue;
      button.setAttribute('aria-pressed',String(this.mode===mode));
      button.classList.toggle('is-active',this.mode===mode);
    }
    if (this.riskBanner && this.riskMessage) {
      const error = this.lastRenderError && !this.ready;
      const danger = !!(error || warnings || omitted || this.previewPaginationIssue);
      this.riskBanner.style.display = danger ? '' : 'none';
      this.riskBanner.setAttribute('data-severity',error || this.previewPaginationIssue ? 'error' : 'warning');
      this.riskMessage.setText(error ? '渲染失败，已停止导出。' : this.previewPaginationIssue
        ? '部分内容超出 A4；可勾选下方“仅打印正常内容”，查看分页结果后保存 PDF。'
        : omitted ? `当前仅打印正常内容，已跳过 ${omitted} 处；PDF 中将保留跳过提示，请查看诊断。`
        : `检测到 ${warnings} 项局部渲染警告；导出前必须检查。`);
    }
    if (this.overflowWarning) this.overflowWarning.style.display = this.previewPaginationIssue || this.overflowOmissionEnabled ? '' : 'none';
    if (this.overflowCheckbox) this.overflowCheckbox.disabled = !!(this.renderBusy || this.sourceDirty || this.sourceReadJob);
    this.updateDiagnostics();
  }

  setRenderBusy(busy) {
    this.renderBusy = busy;
    if (this.refreshPreviewButton) this.refreshPreviewButton.setText(busy ? '取消预览' : '重新预览');
    this.updateCompactStatus();
  }

  cancelPreview(reason = '预览已取消，可切换模式或点击“重新预览”') {
    if (!this.renderController || this.renderController.signal.aborted) return false;
    this.renderController.abort(mwbRenderAbortError(reason));
    return true;
  }

  async collectRenderWarnings(stage, root, source, signal) {
    const warnings = await waitForStableRender(root, source, undefined, undefined, signal);
    // The signal may be cancelled after the awaited promise settles but before
    // this continuation runs. Never leak warnings into the next generation.
    mwbThrowIfRenderAborted(signal);
    this.addRenderWarnings(stage, warnings);
  }

  renderMode(mode) {
    if (this.closed) return Promise.resolve();
    this.cancelSourceRead('预览模式或设置已变化，读取已取消');
    this.cancelPreview('预览模式或设置已变化，旧预览已取消');
    const controller = new AbortController(), signal = controller.signal;
    this.renderController = controller;
    this.setRenderBusy(true);
    this.cancelExport('预览模式或设置已变化，旧导出已取消');
    // Serialize renderer writes so quick mode/setting changes cannot let an
    // outdated MarkdownRenderer invocation corrupt the current preview.
    const generation = ++this.generation;
    this.mode = mode;
    if (this.solutionModeLabels) {
      this.solutionModeLabels.student.style.display = mode === 'student' ? '' : 'none';
      this.solutionModeLabels.teacher.style.display = mode === 'teacher' ? '' : 'none';
    }
    this.ready = false;
    this.spaceDiagnostics = [];
    this.renderWarnings = [];
    this.partialExportApproved = false;
    if (this.partialCheckbox) this.partialCheckbox.checked = false;
    if (this.partialWarning) this.partialWarning.style.display = 'none';
    this.documentRenderSource = null;
    this.previewPaginationIssue = '';
    this.overflowOmissionEnabled = false;
    if (this.overflowCheckbox) this.overflowCheckbox.checked = false;
    this.status.setText('渲染中：' + (this.documentMode ? (mode === 'document' ? '讲义原文' : mode === 'student' ? '讲义学生版' : '讲义教师版') : mode === 'student' ? '学生卷' : '教师卷'));
    if (this.metaCheckboxes) {
      for (const [key,box] of this.metaCheckboxes) box.checked = this.metaSelections[mode]?.includes(key) || false;
    }
    this.lastRenderError = '';
    if (this.copyErrorButton) this.copyErrorButton.style.display = 'none';
    this.renderQueue = this.renderQueue.catch(() => {}).then(async () => {
      if (generation !== this.generation || this.closed) return;
      this.clearPaginatedPreview();
      mwbReleaseRenderOwner(this.plugin, this.renderOwner);
      this.renderOwner = mwbCreateRenderOwner(this.plugin);
      this.questionPlan=null;
      this.rendered.empty();
      this.rendered.removeAttribute('data-mwb-question-policy');
      this.rendered.removeAttribute('data-mwb-question-count');
      try {
        mwbThrowIfRenderAborted(signal);
        if (this.documentMode) {
          this.questionPlan=mwbHandoutQuestionPlan(this.markdown);
          if(this.questionPlan.errors.length)throw new Error(this.questionPlan.errors.map(e=>'第 '+e.line+' 行：'+e.message).join('；'));
          const plan = mwbWithAnswerMeasurement(this.rendered, () => handoutPlan(this.questionPlan.markdown, mode, this.solutionOptions));
          let heights = [];
          if (mode === 'student' && plan.solutionCount) {
            this.status.setText(`正在测量长讲义的 ${plan.solutionCount} 个教师专用块…`);
            heights = await this.measureDocumentSolutions(plan.solutionCount, generation);
            if (generation !== this.generation) return;
          }
          await this.renderDocumentSource(plan.markdown, this.rendered, generation);
          if (generation !== this.generation) return;
          if (mode === 'student' && plan.solutionCount) {
            injectSpaceNodes(this.rendered, heights, this.spaceSettings, this.rendered.ownerDocument, plan.skipSpaces, plan.targets);
          }
          this.solutionHeights = heights.filter((_, index) => !plan.skipSpaces?.includes(index));
          await this.collectRenderWarnings('讲义预览', this.rendered, plan.markdown, signal);
          if (generation !== this.generation) return;
          layoutOptionGrids(this.rendered);
          this.documentRenderSource = plan.markdown;
          mwbApplyHandoutQuestions(this.rendered,this.questionPlan,this.file.path);
        } else if (!this.exam) assertValidQuestionSource(this.markdown);
        if (this.documentMode) {
          // The long Markdown content has already been rendered above.
        } else if (this.exam) {
          await this.renderExam(mode, generation);
        } else if (mode === 'student') {
          const plan = mwbWithAnswerMeasurement(this.rendered, () => studentSpacePlan(this.markdown, this.solutionOptions));
          let heights = [];
          if (plan.count > 0) {
            this.status.setText('正在测量教师专用块的学生卷等高留白…');
            heights = await this.measureSolutions(plan.count, generation);
            if (generation !== this.generation) return;
          }
          await mwbRenderMarkdown(this.app, plan.markdown, this.rendered, this.file.path, this.renderOwner || this.plugin, undefined, signal);
          if (generation !== this.generation) return;
          injectSpaceNodes(this.rendered, heights, this.spaceSettings, this.rendered.ownerDocument, plan.skipSpaces, plan.targets);
          this.solutionHeights = heights.filter((_, index) => !plan.skipSpaces?.includes(index));
          await this.collectRenderWarnings('学生版预览', this.rendered, plan.markdown, signal);
          layoutOptionGrids(this.rendered);
          addMetaBlock(this.rendered.ownerDocument,this.rendered,
            this.sourceMetadata || metadataOf({markdown:this.markdown}),
            this.metaSelections.student,this.metaPosition);
        } else {
          const content = mwbWithAnswerMeasurement(this.rendered, () => transformQuestion(this.markdown, mode, this.solutionOptions));
          await mwbRenderMarkdown(this.app, content, this.rendered, this.file.path, this.renderOwner || this.plugin, undefined, signal);
          if (generation !== this.generation) return;
          await this.collectRenderWarnings('教师版预览', this.rendered, content, signal);
          layoutOptionGrids(this.rendered);
          addMetaBlock(this.rendered.ownerDocument,this.rendered,
            this.sourceMetadata || metadataOf({markdown:this.markdown}),
            this.metaSelections.teacher,this.metaPosition);
          this.solutionHeights = [];
        }
        if (generation !== this.generation) return;
        mwbThrowIfRenderAborted(signal);
        if (!this.documentMode && !this.exam) mwbWrapSingleQuestion(this.rendered,this.file.path);
        if (this.exam) this.rendered.setAttribute('data-mwb-question-policy','strict-h5');
        this.updateQuestionBoundaryReport();
        // Audit actual student PREVIEW geometry after all MathJax and styles
        // settle. The PDF engine may still create pagination gaps independently.
        this.spaceDiagnostics = mode === 'student' ? auditSpaceGeometry(this.rendered) : [];
        // Keep the original continuous DOM for stable PDF preflight checks.
        // Show an A4-paginated clone using the SAME paginator as PDF output.
        let previewNote = '';
        try {
          const pagination = this.showPaginatedPreview();
          previewNote = `；A4 分页预览 ${pagination.pages} 页（PDF 导出时重新核验）` +
            (pagination.relaxedGroupBindings?.length ? `；${pagination.relaxedGroupBindings.length} 处题干与首步合计超过整页，已采用续页` : '');
        } catch (error) {
          this.clearPaginatedPreview();
          this.previewPaginationIssue = String(error?.message || error).slice(0,1000);
          previewNote = '；A4 分页预览失败，当前显示连续内容：' + this.previewPaginationIssue;
          console.warn('[Mathsemble] A4 预览分页失败', error);
        }
        this.ready = true;
        const extra = mode === 'student' && this.solutionHeights.length
          ? `；${this.solutionHeights.length} 处答题区按解答高度 ${this.spaceSettings.ratio}%（最低 ${this.spaceSettings.minimumCm} cm）生成`
          : '';
        const roles = this.documentMode ? (mode === 'document' ? '长 Markdown 原文' : mode === 'student' ? '长 Markdown 学生版' : '长 Markdown 教师版') : this.exam ? teachingRoleSummary(this.exam.items)
          : teachingRoleSummary([{ markdown:this.markdown }]);
        const previewInfo = extra + '；教学角色：' + roles +
          '；留白几何核验 ' + this.spaceDiagnostics.length + ' 项' + previewNote +
          (this.questionPlan ? `；按五级标题识别 ${this.questionPlan.groups.length} 个块，${this.questionPlan.warnings.length} 处边界提示` : '') + '。' +
          (this.exam ? ` 共 ${this.exam.items.length} 题。` : this.documentMode ? ` 文档 ${this.markdown.length} 字符。` : '');
        const warnings = [...new Set(this.renderWarnings)];
        this.renderWarnings = warnings;
        if (warnings.length) {
          this.lastRenderError = ['Mathsemble 局部渲染警告',
            '模式：' + mode, '警告数：' + warnings.length, ...warnings].join('\n');
          if (this.copyErrorButton) this.copyErrorButton.style.display = '';
          if (this.partialWarning) this.partialWarning.style.display = '';
          this.status.setText(`预览已生成，但有 ${warnings.length} 项局部渲染警告。` +
            ' 部分内容可能错误或缺失；请复制错误详情检查。' +
            ' 如确需输出，请勾选“允许导出不完整的 PDF”。\n' +
            summarizeRenderIssues(warnings, 3) + previewInfo);
          if (!this.silentRender) new Notice(`预览存在 ${warnings.length} 项局部渲染警告；确认后仍可单独保存当前版 PDF。`, 12000);
        } else {
          this.status.setText('预览渲染检查通过' + previewInfo);
        }
        this.updateCompactStatus();
      } catch (e) {
        if (generation !== this.generation) return;
        mwbReleaseRenderOwner(this.plugin, this.renderOwner);
        this.renderOwner = null;
        if (e?.code === 'MWB_RENDER_ABORTED') {
          this.status.setText(e.message);
          this.updateCompactStatus();
          return;
        }
        const detail = String(e?.message || e);
        this.lastRenderError = ['Mathsemble v' + (this.plugin.manifest?.version || 'unknown'),
          '模式：' + (mode === 'student' ? '学生版' : mode === 'teacher' ? '教师版' : '原文'),
          '入口：' + (this.documentMode ? '长 Markdown 讲义' : this.exam ? '当前文件夹整卷' : '当前题卡'),
          '错误：' + detail,
          e?.stack ? '调用栈：' + e.stack : '',
        ].filter(Boolean).join('\n');
        this.status.setText('渲染失败，已停止 PDF 导出。\n' + detail);
        this.updateCompactStatus();
        if (this.copyErrorButton) this.copyErrorButton.style.display = '';
        console.error('[Mathsemble] 预览渲染失败', this.lastRenderError, e);
        if (!this.silentRender) new Notice('渲染失败：' + detail.slice(0, 240), 12000);
      } finally {
        this.removeMeasurement();
        if (this.renderController === controller) {
          this.renderController = null;
          if (!this.closed) this.setRenderBusy(false);
        }
      }
    });
    return this.renderQueue;
  }

  updateQuestionBoundaryReport() {
    if(!this.questionBoundaryPanel)return;
    const plan=this.questionPlan;
    const labels=new Map(Array.from(this.rendered?.querySelectorAll('[data-mwb-question-id]') || [],
      q=>[q.getAttribute('data-mwb-question-id'),q.getAttribute('data-mwb-question-label') || '块']));
    const rows=plan ? [
      `五级标题构成的块：${plan.groups.length} 个；块内六级标题、小问及 Callout 不结束当前块。`,
      ...plan.groups.map((g,i)=>`块${i+1} ${labels.get(g.id) || '块'}｜源码 ${g.start+1}—${g.end} 行｜answer ${g.answerCount}，solution ${g.solutionCount}`),
      // Source warnings may quote a raw answer-bearing heading. Student
      // diagnostics retain location/type without reproducing that source.
      ...plan.warnings.map(w=>`注意：第 ${w.line} 行，${this.mode==='student' ? '块边界提示（'+w.code+'），请在教师版或原文中检查' : w.message}`),
    ] : ['题卡／文件夹组卷：沿用一题一容器，短题不拆，长题新页起排。'];
    if(plan && !plan.groups.length)rows.push('当前没有五级内容块；普通正文不享有整块分页保护。请使用 ##### 标题 开始一个块。');
    this.questionBoundaryPanel.setText(rows.join('\n'));
  }

  updateQuestionBounds() {
    if(!this.previewPages)return;
    this.previewPages.classList.toggle('mwb-show-question-bounds',this.showQuestionBounds);
    for(const q of this.previewPages.querySelectorAll('[data-mwb-question-id]')){
      q.title=(q.getAttribute('data-mwb-question-label') || '块')+
        (q.getAttribute('data-mwb-source-start') ? `｜源码 ${q.getAttribute('data-mwb-source-start')}—${q.getAttribute('data-mwb-source-end')} 行` : '');
    }
  }

  clearPaginatedPreview() {
    if (this.previewPages) this.previewPages.remove();
    this.previewPages = null;
    this.previewPaginationReport = null;
    if (this.page) {
      this.page.classList.remove('mwb-preview-source');
      this.page.removeAttribute('aria-hidden');
    }
  }

  showPaginatedPreview() {
    this.clearPaginatedPreview();
    // Reuse the already typeset MathJax/SVG DOM, without editing the source
    // needed for subsequent PDF/HTML export and writing-height audits.
    const view = this.rendered.cloneNode(true);
    view.classList.add('mwb-export-doc', 'mwb-preview-pages');
    expandPrintCallouts(view);
    this.page.after(view);
    try {
      const report = paginatePreviewDocument(view, false, true, !!this.overflowOmissionEnabled);
      this.previewPages = view;
      this.previewPaginationReport = report;
      this.updateQuestionBounds();
      // Visibility/positioning retain the original DOM's measurable geometry.
      // display:none would make the student blank-space audit report 0 height.
      this.page.classList.add('mwb-preview-source');
      this.page.setAttribute('aria-hidden', 'true');
      return report;
    } catch (error) {
      view.remove();
      throw error;
    }
  }

  // Preserve complete Markdown headings, fences, and source-file context.
  // Rendering in manageable chunks keeps large handouts responsive, while the
  // geometry measurement uses exactly the same typography and renderer.
  async renderDocumentSource(source, target, generation, owner = this.renderOwner || this.plugin, signal = this.renderController?.signal) {
    // Keep one document parse for references/footnotes. The shared renderer
    // already owns a connected staging node; a second detached wrapper breaks
    // third-party renderers that require real geometry during render().
    const chunks = this.questionPlan ? [source] : documentChunks(source);
    for (const chunk of chunks) {
      if (generation !== this.generation) return;
      mwbThrowIfRenderAborted(signal);
      await mwbRenderMarkdown(this.app, chunk, target, this.file.path, owner, undefined, signal);
      mwbThrowIfRenderAborted(signal);
    }
  }

  async measureDocumentSolutions(expectedCount, generation) {
    const signal = this.renderController?.signal;
    mwbThrowIfRenderAborted(signal);
    const {page:measure, owner} = this.createMeasurement();
    try {
      const measurement = mwbWithAnswerMeasurement(this.rendered, () => mwbTeacherMeasurementPlan(this.markdown, this.solutionOptions));
      const source = measurement.markdown;
      await this.renderDocumentSource(source, measure, generation, owner, signal);
      if (generation !== this.generation) return [];
      try {
        await this.collectRenderWarnings('教师专用块高度测量', measure, source, signal);
      } catch (error) {
        if (error?.code === 'MWB_RENDER_ABORTED') throw error;
        throw new Error('教师专用块高度测算失败：' + (error?.message || error));
      }
      if (generation !== this.generation) return [];
      assertMeasurementWidth(this.rendered, measure);
      layoutOptionGrids(measure);
      return teacherSolutionHeights(measure, expectedCount, measurement);
    } finally {
      this.removeMeasurement(measure);
    }
  }

  // Entire-folder exam: each note is rendered in its own source-path context
  // so ![[image.png]] and other vault-relative resources remain resolvable.
  async renderExam(mode, generation) {
    const signal = this.renderController?.signal;
    mwbThrowIfRenderAborted(signal);
    const items = this.exam.items;
    if (!items.length) throw new Error('没有有效题卡');
    // Reject bad source before any partial exam rendering/printing.
    for (const item of items) {
      try { assertValidQuestionSource(item.markdown); }
      catch(e) { throw new Error(`${item.file.path}：${e.message || e}`); }
    }
    this.titleElement = this.rendered.createEl('h1', {cls:'mwb-exam-title',text:this.examTitle});
    this.rendered.createDiv({cls:'mwb-exam-edition',text:mode === 'student' ? '学生版' : '教师版'});
    const teacherHeightMap = mode === 'student' ? await this.measureExamSolutions(items, generation) : new Map();
    if (generation !== this.generation) return;
    let currentSection = null;
    const contexts = [];
    let spaces = 0;
    for (const item of items) {
      if (generation !== this.generation) return;
      if (item.sectionKey !== currentSection) {
        currentSection = item.sectionKey;
        const heading = this.exam.sections.find(section => section.id === currentSection);
        this.rendered.createEl('h2', {cls:'mwb-exam-section', text:heading.title});
      }
      const wrapper = this.rendered.createEl('section', {cls:'mwb-exam-question'});
      wrapper.setAttribute('data-mwb-question-number', String(item.number));
      wrapper.setAttribute('data-mwb-source-path', item.file.path);
      if (item.teachingRole?.role) wrapper.setAttribute('data-mwb-teaching-role', item.teachingRole.role);
      const content = wrapper.createDiv({cls:'mwb-exam-question-content'});
      let source;
      if (mode === 'student') {
        const plan = mwbWithAnswerMeasurement(this.rendered, () => studentSpacePlan(item.markdown, this.solutionOptions));
        source = plan.markdown;
        await mwbRenderMarkdown(this.app, source, content, item.file.path, this.renderOwner || this.plugin, undefined, signal);
        if (generation !== this.generation) return;
        if (plan.count > 0) {
          const heights = teacherHeightMap.get(item.file.path);
          if (!heights || heights.length !== plan.count) throw new Error('教师专用块高度数量与题卡不匹配：' + item.file.path);
          injectSpaceNodes(content, heights, this.spaceSettings, content.ownerDocument, plan.skipSpaces, plan.targets);
          spaces += heights.length - (plan.skipSpaces?.length || 0);
        }
      } else {
        source = mwbWithAnswerMeasurement(this.rendered, () => transformQuestion(item.markdown, 'teacher', this.solutionOptions));
        await mwbRenderMarkdown(this.app, source, content, item.file.path, this.renderOwner || this.plugin, undefined, signal);
      }
      mwbThrowIfRenderAborted(signal);
      if (generation !== this.generation) return;
      insertQuestionNumber(content, item.number);
      addMetaBlock(content.ownerDocument,content,metadataOf(item),this.metaSelections[mode] || [],this.metaPosition);
      contexts.push({content, source, path:item.file.path});
    }
    if (generation !== this.generation) return;
    await this.collectRenderWarnings('整卷预览', this.rendered, contexts.map(x=>x.source).join('\n\n'), signal);
    this.validateExamContexts(contexts, '整卷题卡');
    layoutOptionGrids(this.rendered);
    markShortQuestions(this.rendered);
    this.solutionHeights = Array(spaces).fill(1);
  }

  validateExamContexts(contexts, stage = '整卷题卡') {
    for (const {content, source, path} of contexts) {
      const {warnings, blockers} = divideRenderIssues(content, issuesInRenderedNode(content, source));
      if (blockers.length) throw new Error(`${path}：${summarizeRenderIssues(blockers)}`);
      this.addRenderWarnings(`${stage}/${path}`, warnings);
    }
  }

  async measureExamSolutions(items, generation = this.generation) {
    const signal = this.renderController?.signal;
    mwbThrowIfRenderAborted(signal);
    this.removeMeasurement();
    const plans = items.map(item => ({item, plan:mwbWithAnswerMeasurement(this.rendered, () => studentSpacePlan(item.markdown, this.solutionOptions))})).filter(x=>x.plan.count>0);
    if (!plans.length) return new Map();
    this.status.setText(`正在测量 ${plans.length} 道题的教师专用块高度…`);
    const {page, owner} = this.createMeasurement();
    const contexts = [];
    try {
      for (const {item,plan} of plans) {
        mwbThrowIfRenderAborted(signal);
        if (generation !== this.generation) return new Map();
        const holder = page.createDiv({cls:'mwb-exam-question-content'});
        const measurement = mwbWithAnswerMeasurement(this.rendered, () => mwbTeacherMeasurementPlan(item.markdown, this.solutionOptions));
        const source = measurement.markdown;
        await mwbRenderMarkdown(this.app, source, holder, item.file.path, owner, undefined, signal);
        mwbThrowIfRenderAborted(signal);
        if (generation !== this.generation) return new Map();
        contexts.push({item,plan,measurement,content:holder,source,path:item.file.path});
      }
      await this.collectRenderWarnings('整卷教师高度测量', page, contexts.map(x=>x.source).join('\n\n'), signal);
      assertMeasurementWidth(this.rendered, page);
      this.validateExamContexts(contexts, '教师高度测量');
      layoutOptionGrids(page);
      const map = new Map();
      for (const {item,plan,measurement,content} of contexts) {
        map.set(item.file.path, teacherSolutionHeights(content,plan.count,measurement));
      }
      return map;
    } finally {
      this.removeMeasurement(page);
    }
  }

  async measureSolutions(count, generation = this.generation) {
    const signal = this.renderController?.signal;
    mwbThrowIfRenderAborted(signal);
    const {page:teacher, owner} = this.createMeasurement();
    try {
      const measurement = mwbWithAnswerMeasurement(this.rendered, () => mwbTeacherMeasurementPlan(this.markdown, this.solutionOptions));
      const source = measurement.markdown;
      await mwbRenderMarkdown(this.app, source, teacher, this.file.path, owner, undefined, signal);
      mwbThrowIfRenderAborted(signal);
      if (generation !== this.generation) return [];
      await this.collectRenderWarnings('教师专用块高度测量', teacher, source, signal);
      assertMeasurementWidth(this.rendered, teacher);
      layoutOptionGrids(teacher);
      return teacherSolutionHeights(teacher, count, measurement);
    } finally {
      this.removeMeasurement(teacher);
    }
  }

  createMeasurement() {
    this.removeMeasurement();
    const parent = this.renderOwner || this.plugin;
    const owner = mwbCreateRenderOwner(parent);
    try {
      const page = this.page.createDiv({cls:'mwb-measure-layer mwb-typography mwb-print-document'});
      this.measurePage = page;
      this.measureOwner = owner;
      this.measureParent = parent;
      return {page, owner};
    } catch (error) { mwbReleaseRenderOwner(parent, owner); throw error; }
  }

  removeMeasurement(expected = this.measurePage) {
    if (expected !== this.measurePage) return;
    const page = this.measurePage, owner = this.measureOwner, parent = this.measureParent;
    this.measurePage = this.measureOwner = this.measureParent = null;
    try { page?.remove(); }
    finally { mwbReleaseRenderOwner(parent, owner); }
  }

  async preparePrintHtml(title, options = {}) {
    mwbThrowIfExportAborted(options.signal);
    if (!this.ready) throw new Error('渲染尚未通过，不能导出');
    await this.assertSourceCurrent(options.signal);
    mwbThrowIfExportAborted(options.signal);
    // Recheck immediately before cloning: an editor change/theme layout or
    // asynchronous TikZ could invalidate the geometry seen earlier.
    const source = this.documentMode ? this.documentRenderSource : this.exam
      ? this.exam.items.map(item => this.mode === 'student' ? mwbWithAnswerMeasurement(this.rendered, () => studentSpacePlan(item.markdown, this.solutionOptions)).markdown : mwbWithAnswerMeasurement(this.rendered, () => transformQuestion(item.markdown, 'teacher', this.solutionOptions))).join('\n\n')
      : this.mode === 'student' ? mwbWithAnswerMeasurement(this.rendered, () => studentSpacePlan(this.markdown, this.solutionOptions)).markdown : mwbWithAnswerMeasurement(this.rendered, () => transformQuestion(this.markdown, this.mode, this.solutionOptions));
    if (this.documentMode && typeof source !== 'string') throw new Error('讲义渲染状态已过期，请重新预览');
    // Reuse the same axis-aware geometry audit as the preview. Avoid a
    // second generic check that loses the offending formula's identity.
    const {warnings, blockers} = divideRenderIssues(this.rendered, issuesInRenderedNode(this.rendered, source));
    if (blockers.length) throw new Error('预览存在严重问题：' + summarizeRenderIssues(blockers));
    let newWarning = false;
    for (const warning of warnings) {
      const issue = '导出前复检：' + warning;
      if (!this.renderWarnings.some(existing => existing.endsWith('：' + warning))) {
        this.renderWarnings.push(issue);
        newWarning = true;
      }
    }
    if (newWarning && this.partialWarning) {
      this.partialExportApproved = false;
      if (this.partialCheckbox) this.partialCheckbox.checked = false;
      this.partialWarning.style.display = '';
      this.status.setText('导出前复检又发现局部渲染警告，请阅读警告并确认后重试。\n' +
        summarizeRenderIssues(warnings, 3));
    }
    if (this.mode === 'student') auditSpaceGeometry(this.rendered);
    const warningsBeforeExamAudit = this.renderWarnings.length;
    if (this.exam) {
      const nodes = [...this.rendered.querySelectorAll('.mwb-exam-question-content')];
      if (nodes.length !== this.exam.items.length) throw new Error('组卷题数与预览节点数不匹配，已阻止导出');
      this.validateExamContexts(nodes.map((content,i) => ({content, source: this.mode === 'student' ? mwbWithAnswerMeasurement(this.rendered, () => studentSpacePlan(this.exam.items[i].markdown, this.solutionOptions)).markdown : mwbWithAnswerMeasurement(this.rendered, () => transformQuestion(this.exam.items[i].markdown, 'teacher', this.solutionOptions)), path:this.exam.items[i].file.path})));
    }
    if (this.renderWarnings.length > warningsBeforeExamAudit && this.partialWarning) {
      this.partialExportApproved = false;
      if (this.partialCheckbox) this.partialCheckbox.checked = false;
      this.partialWarning.style.display = '';
      this.status.setText('导出前发现新的局部渲染问题，请查看错误详情、重新确认后再输出。');
    }
    this.assertPartialExportApproved();
    return await exportHtml(this.rendered, title, typographyCss, this.rendered.ownerDocument || document, {
      signal:options.signal, onResourceReport:options.onResourceReport,
      allowIncompleteImages: this.partialExportApproved && this.renderWarnings.some(issue =>
        /未加载或加载失败的图片/.test(issue))
    });
  }

  setExportBusy(busy) {
    // Freeze parameters for a pair; mode/refresh buttons remain usable and
    // cancel the batch through the existing generation guard.
    if (busy && this.exportJob?.kind === 'dual' && !this.dualDisabledControls) {
      this.dualDisabledControls = new Map();
      for (const input of this.contentEl?.querySelectorAll?.('input, select') || []) {
        if (input === this.partialCheckbox) continue; // Revocation still cancels.
        this.dualDisabledControls.set(input, input.disabled);
        input.disabled = true;
      }
    } else if (!busy && this.dualDisabledControls) {
      for (const [input, disabled] of this.dualDisabledControls) input.disabled = disabled;
      this.dualDisabledControls = null;
    }
    for (const button of this.exportButtons || []) button.disabled = !!(busy || this.sourceDirty || this.sourceReadJob);
    if (this.cancelExportButton) {
      this.cancelExportButton.style.display = busy ? '' : 'none';
      this.cancelExportButton.disabled = !busy;
    }
    this.updateCompactStatus();
  }

  beginExport(kind) {
    if (this.sourceDirty || this.sourceReadJob) { new Notice('源文件已变化或正在读取，请先读取最新内容并完成预览'); return null; }
    if (this.exportJob) { new Notice('已有导出任务，请完成或取消后再操作'); return null; }
    if (!this.ready || this.closed) { new Notice('渲染尚未通过，不能输出'); return null; }
    if (kind === 'dual' && this.overflowOmissionEnabled) {
      new Notice('仅打印正常内容适用于当前版 PDF；请分别预览、保存所需版本。'); return null;
    }
    if (kind !== 'dual' && this.renderWarnings.length && !this.partialExportApproved) {
      new Notice('存在局部渲染警告：请先检查错误并勾选允许不完整输出，再保存当前版 PDF。', 9000);
      return null;
    }
    const job = {kind, generation:this.generation, mode:this.mode, controller:new AbortController(),
      savedPath:null, resources:null};
    this.exportJob = job;
    this.setExportBusy(true);
    return job;
  }

  cancelExport(reason = '导出已取消') {
    const job = this.exportJob;
    if (!job || job.controller.signal.aborted) return;
    job.controller.abort(mwbExportAbortError(reason));
    if (this.isCurrentExport(job)) {
      this.status.setText('正在取消导出；已保存的文件及已提交的打印任务不会撤回。');
      if (this.cancelExportButton) this.cancelExportButton.disabled = true;
    }
    // Keep the mutex until cleanup (or a started, non-cancellable Vault write)
    // has settled. Cancellation alone must not admit a second file operation.
  }

  isCurrentExport(job) {
    return !this.closed && this.exportJob === job && job.generation === this.generation && job.mode === this.mode;
  }

  assertCurrentExport(job) {
    mwbThrowIfExportAborted(job.controller.signal);
    if (!this.isCurrentExport(job)) throw mwbExportAbortError('预览内容已变化，旧导出已取消');
    if (this.sourceDirty || this.sourceReadJob) throw mwbSourceError('源文件已变化，请读取最新内容后再导出');
  }

  finishExport(job) {
    if (this.exportJob !== job) return;
    this.exportJob = null;
    if (!this.closed) this.setExportBusy(false);
  }

  resourceSummary(job) {
    return job.resources ? `；资源读取 ${job.resources.reads} 次，缓存复用 ${job.resources.cacheHits} 次` : '';
  }

  reportExportFailure(job, error) {
    if (!this.isCurrentExport(job)) return; // Never overwrite a newer render's status.
    const cancelled = error?.name === 'AbortError';
    const prefix = job.savedPath ? `已保存：${job.savedPath}；后续操作` : '导出';
    const message = prefix + (cancelled ? '已取消：' : '失败：') + (error?.message || String(error));
    this.status.setText(message);
    new Notice(message, cancelled ? 5000 : 10000);
  }

  async saveHtml() {
    const job = this.beginExport('html');
    if (!job) return;
    this.status.setText('正在准备 HTML 图片与字体资源…');
    try {
      const name = `${safeStem(this.exam ? this.examTitle : this.file.basename)}_${job.mode}_${stamp()}.html`;
      const html = await this.preparePrintHtml(name, {signal:job.controller.signal,
        onResourceReport:report => { job.resources = report; }});
      this.assertCurrentExport(job);
      await ensureExportFolder(this.app);
      await this.assertSourceCurrent(job.controller.signal);
      this.assertCurrentExport(job);
      // Obsidian Vault.create cannot be aborted after it has started. Keep
      // the export mutex until completion; never delete a saved user file.
      await this.app.vault.create(`${OUTPUT_DIR}/${name}`, html);
      job.savedPath = `${OUTPUT_DIR}/${name}`;
      this.assertCurrentExport(job);
      this.status.setText('HTML 已保存：' + job.savedPath + this.resourceSummary(job));
      new Notice('已保存自包含 HTML：' + job.savedPath);
    } catch (error) { this.reportExportFailure(job, error); }
    finally { this.finishExport(job); }
  }

  async exportPdf({save=true,printAfter=false} = {}) {
    const job = this.beginExport(printAfter ? 'print' : 'pdf');
    if (!job) return;
    this.status.setText('正在准备 A4 打印页面、核验 PDF…');
    try {
      const name=`${safeStem(this.exam ? this.examTitle : this.file.basename)}_${job.mode}${this.overflowOmissionEnabled ? '_部分内容' : ''}_${stamp()}.pdf`;
      const html=await this.preparePrintHtml(name, {signal:job.controller.signal,
        onResourceReport:report => { job.resources = report; }});
      this.assertCurrentExport(job);
      const pdf=await this.buildPdfBuffer(html,{
        signal:job.controller.signal,
        allowOverflowOmission: !!this.overflowOmissionEnabled,
        printAfter,
        beforePrint:async() => { await this.assertSourceCurrent(job.controller.signal); this.assertCurrentExport(job); },
        // Consent remains category-specific. Cancellation and timeout never
        // count as permission to omit content or bypass pagination audits.
        allowPartialMath: this.partialExportApproved && this.renderWarnings.some(issue =>
          /MathJax|KaTeX|公式 #.*尺寸为零/.test(issue)),
        allowPartialImage: this.partialExportApproved && this.renderWarnings.some(issue =>
          /未加载或加载失败的图片/.test(issue)),
        onPdfReady:save ? async buffer=>{
          this.assertCurrentExport(job);
          await ensureExportFolder(this.app);
          await this.assertSourceCurrent(job.controller.signal);
          this.assertCurrentExport(job);
          const bytes=buffer.buffer.slice(buffer.byteOffset,buffer.byteOffset+buffer.byteLength);
          const savedPath=`${OUTPUT_DIR}/${name}`;
          await this.app.vault.createBinary(savedPath,bytes);
          job.savedPath=savedPath;
          if (this.isCurrentExport(job)) {
            this.lastSavedPdfPath = savedPath;
            if (this.openPdfButton) this.openPdfButton.style.display = '';
          }
          this.assertCurrentExport(job);
        } : undefined,
      });
      this.assertCurrentExport(job);
      const printOutcome=pdf.mwbPrintOutcome;
      const printMessage=!printAfter?'':printOutcome?.success?'；打印任务已提交到系统':
        `；打印取消或失败：${printOutcome?.reason || '未知原因'}`;
      const pagination=pdf.mwbPrintReport;
      const partialLabel = (this.renderWarnings.length ? `；带 ${this.renderWarnings.length} 项局部渲染警告（内容可能不完整）` : '') +
        (pagination?.omittedBlocks?.length ? `；已跳过 ${pagination.omittedBlocks.length} 处超出 A4 的内容（原位已标记）` : '');
      this.status.setText((job.savedPath ? `PDF 已保存：${job.savedPath}` : 'PDF 已生成（未保存）')+printMessage+
        (pagination ? `；${pagination.pages} 页` : '')+
        (pagination?.relaxedGroupBindings?.length ? `；${pagination.relaxedGroupBindings.length} 处超长题组已续页` : '')+
        partialLabel+this.resourceSummary(job));
      new Notice((job.savedPath?'PDF 已保存':'PDF 已生成')+partialLabel+printMessage,8500);
    } catch(error) { this.reportExportFailure(job, error); }
    finally { this.finishExport(job); }
  }


  buildPdfBuffer(html, options) {
    return pdfBufferFromHtml(html, electronWindowConstructor(), options);
  }

  dualExportSettings() {
    return {spaceSettings:{...this.spaceSettings}, solutionOptions:{...this.solutionOptions},
      metaSelections:{student:[...this.metaSelections.student], teacher:[...this.metaSelections.teacher]},
      metaPosition:this.metaPosition, examTitle:this.examTitle};
  }

  assertDualExport(job) {
    this.assertCurrentExport(job);
    if (job.input.sourceSnapshot !== this.sourceSnapshot || job.input.sourceRevision !== this.sourceRevision)
      throw mwbSourceError('源文快照已变化，双版导出已停止');
    if (job.input.settingsKey !== JSON.stringify(this.dualExportSettings()))
      throw mwbExportAbortError('输出设置已变化，双版导出已取消');
  }

  createDualExportWorker(input) {
    const doc = this.rendered.ownerDocument;
    const mount = doc.createElement('section');
    mount.className = 'mwb-modal mwb-dual-export-host';
    mount.setAttribute('aria-hidden', 'true');
    mount.inert = true;
    // Not display:none/visibility:hidden: teacher height and formula geometry
    // must be measured in the parent's real Document and typography context.
    mount.style.cssText = 'position:fixed;left:-100000px;top:0;width:210mm;max-width:none;opacity:0;pointer-events:none;';
    let worker;
    try {
      this.contentEl.appendChild(mount);
      worker = new PreviewModal(this.app, this.plugin, input.file, input.markdown, input.exam,
        {documentMode:input.documentMode, sourceScope:input.sourceScope, sourceSnapshot:input.sourceSnapshot});
      Object.assign(worker, JSON.parse(input.settingsKey));
      worker.silentRender = true;
      worker.modalEl = mount;
      worker.contentEl = mount.createDiv();
      worker.status = worker.contentEl.createDiv({cls:'mwb-status'});
      worker.page = worker.contentEl.createDiv({cls:'mwb-page'});
      worker.rendered = worker.page.createDiv({cls:'mwb-typography mwb-print-document'});
      return {worker, dispose:() => {try { worker.onClose(); } finally { mount.remove(); }}};
    } catch (error) {
      try { worker?.onClose(); } finally { mount.remove(); }
      throw error;
    }
  }

  async generateDualEdition(job, edition, name) {
    this.assertDualExport(job);
    const context = this.createDualExportWorker(job.input), worker = context.worker;
    const signal = job.controller.signal;
    const stop = () => worker.cancelPreview('双版导出已取消');
    signal.addEventListener('abort', stop, {once:true});
    try {
      this.assertDualExport(job);
      await worker.renderMode(edition);
      this.assertDualExport(job);
      if (!worker.ready) throw new Error(worker.lastRenderError || '该版本未完成渲染');
      if (worker.renderWarnings.length)
        throw new Error('该版本有局部渲染警告；双版导出不继承其他版本的许可。请修正问题，或切换到该版本确认后单独保存。\n' + worker.renderWarnings.join('\n'));
      // A continuous fallback is useful for interactive diagnosis, not for
      // claiming that a batch has already passed the same pagination audit.
      if (!worker.previewPaginationReport?.pages)
        throw new Error('该版本 A4 分页预览失败，双版导出已停止');
      let resources = null;
      const html = await worker.preparePrintHtml(name, {signal,
        onResourceReport:report => { resources = report; }});
      this.assertDualExport(job);
      const pdf = await this.buildPdfBuffer(html, {signal, printAfter:false,
        allowPartialMath:false, allowPartialImage:false});
      this.assertDualExport(job);
      return {pdf, pages:pdf.mwbPrintReport?.pages || 0, resources};
    } finally {
      signal.removeEventListener('abort', stop);
      context.dispose();
    }
  }

  showDualExportReport(report) {
    if (this.closed || !this.dualReportEl || this.lastDualExportReport !== report) return;
    const panel = this.dualReportEl;
    panel.empty();
    panel.style.display = '';
    panel.createEl('strong', {text:report.summary});
    const states = {pending:'尚未生成', rendering:'正在生成', prepared:'已生成，尚未保存',
      saving:'正在保存', saved:'已保存', failed:'失败', unverified:'写入结果未确认，请核对目标文件', cancelled:'已取消，未保存', 'not-run':'未执行'};
    for (const item of report.items) {
      const row = panel.createDiv();
      row.createEl('span', {text:`${item.label}：${states[item.state] || item.state}` +
        (item.pages ? `（${item.pages} 页）` : '') + (item.savedPath || item.unverifiedPath ? ` ${item.savedPath || item.unverifiedPath}` : '')});
      if (item.savedPath) {
        const open = row.createEl('button', {text:'打开' + item.label + ' PDF'});
        open.onclick = async () => {
          try { await openExportedPdf(this.app, item.savedPath); }
          catch (error) { new Notice('打开 PDF 失败：' + (error?.message || error), 10000); }
        };
      }
    }
    if (report.error) panel.createEl('p', {text:report.error});
    this.updateCompactStatus();
  }

  async exportBothPdf() {
    const job = this.beginExport('dual');
    if (!job) return;
    const report = {version:this.plugin?.manifest?.version || 'unknown',
      startedAt:new Date().toISOString(), outcome:'running', summary:'双版导出：正在核验源文…',
      items:[{edition:'student', label:'学生版', state:'pending'},
        {edition:'teacher', label:'教师版', state:'pending'}], error:null};
    this.lastDualExportReport = report;
    const generated = [];
    let active = null;
    try {
      // Strings and frozen source records are shared, while mutable UI options
      // and grouping arrays are copied before the first await.
      job.input = {file:this.file, markdown:this.markdown, documentMode:this.documentMode,
        exam:this.exam ? {...this.exam, items:this.exam.items.map(item => ({...item})),
          sections:this.exam.sections.map(section => ({...section}))} : null,
        sourceScope:{...this.sourceScope}, sourceSnapshot:this.sourceSnapshot,
        sourceRevision:this.sourceRevision, settingsKey:JSON.stringify(this.dualExportSettings())};
      this.showDualExportReport(report);
      await this.assertSourceCurrent(job.controller.signal);
      this.assertDualExport(job);
      const stem = `${safeStem(this.exam ? this.examTitle : this.file.basename)}_${stamp()}`;
      // A collision must never overwrite an earlier pair. Vault.createBinary
      // remains the final exclusive-create check against concurrent windows.
      let suffix = '', paths;
      for (let attempt=0; attempt<100; attempt++) {
        suffix = attempt ? `_${attempt}` : '';
        paths = report.items.map(item => `${OUTPUT_DIR}/${stem}${suffix}_${item.label}.pdf`);
        if (paths.every(path => !this.app.vault.getAbstractFileByPath(path))) break;
        paths = null;
      }
      if (!paths) throw new Error('无法分配不冲突的双版文件名，请重试');
      for (const [index,item] of report.items.entries()) {
        active = item;
        item.state = 'rendering';
        report.summary = `双版导出：正在生成${item.label}（${index+1}/2）…`;
        this.status.setText(report.summary);
        this.showDualExportReport(report);
        const result = await this.generateDualEdition(job, item.edition, paths[index].split('/').pop());
        this.assertDualExport(job);
        item.pages = result.pages;
        item.resources = result.resources;
        item.state = 'prepared';
        generated.push({item, pdf:result.pdf, path:paths[index]});
      }
      active = null;
      // Nothing is written until BOTH editions render and paginate successfully.
      await ensureExportFolder(this.app);
      await this.assertSourceCurrent(job.controller.signal);
      this.assertDualExport(job);
      if (paths.some(path => this.app.vault.getAbstractFileByPath(path)))
        throw new Error('输出文件名已被占用，未保存本组 PDF，请重试');
      for (const entry of generated) {
        active = entry.item;
        await this.assertSourceCurrent(job.controller.signal);
        this.assertDualExport(job);
        active.state = 'saving';
        active.attemptedPath = entry.path;
        report.summary = '双版导出：正在保存' + active.label + '…';
        this.status.setText(report.summary);
        this.showDualExportReport(report);
        const bytes = entry.pdf.buffer.slice(entry.pdf.byteOffset, entry.pdf.byteOffset + entry.pdf.byteLength);
        // A Vault write already in progress is not abortable. Record successful
        // writes BEFORE the post-write cancellation check; never delete them.
        await this.app.vault.createBinary(entry.path, bytes);
        active.savedPath = entry.path;
        active.state = 'saved';
        job.savedPath = entry.path;
        if (this.isCurrentExport(job)) {
          this.lastSavedPdfPath = entry.path;
          if (this.openPdfButton) this.openPdfButton.style.display = '';
        }
        entry.pdf = null;
        this.assertDualExport(job);
      }
      report.outcome = 'complete';
      report.summary = '双版 PDF 已保存：学生版、教师版各一份。';
    } catch (error) {
      const cancelled = error?.name === 'AbortError';
      report.error = error?.message || String(error);
      if (active?.state === 'saving') {
        // An I/O rejection may occur after bytes reached disk. Never label an
        // unconfirmed write as either a valid PDF or definitely no file.
        active.state = 'unverified';
        active.unverifiedPath = active.attemptedPath;
      } else if (active && active.state !== 'saved') active.state = cancelled ? 'cancelled' : 'failed';
      for (const item of report.items) {
        if (item.state === 'pending') item.state = 'not-run';
        if (item.state === 'prepared') item.state = 'cancelled';
      }
      const saved = report.items.filter(item => item.savedPath).length;
      report.outcome = saved ? (saved===2 ? 'saved-after-interruption' : 'partial') : (cancelled ? 'cancelled' : 'failed');
      const uncertain = report.items.filter(item => item.unverifiedPath).length;
      report.summary = uncertain ? `双版保存中断：已确认 ${saved}/2 份保存成功，${uncertain} 份写入结果未确认，请核对目标文件。` : saved===2 ? '操作中断时两份文件已经写入；文件均已保留。' : saved
        ? '双版导出仅保存了 1/2 份；已保存文件保留，未完成的版本见下方。'
        : `双版导出${cancelled ? '已取消' : '失败'}，未保存任何 PDF。`;
    } finally {
      generated.length = 0;
      report.finishedAt = new Date().toISOString();
      this.showDualExportReport(report);
      if (this.isCurrentExport(job)) this.status.setText(report.summary + (report.error ? '\n' + report.error : ''));
      if (!this.closed || report.items.some(item => item.savedPath || item.unverifiedPath)) new Notice(report.summary, 10000);
      this.finishExport(job);
    }
    return report;
  }

  onClose() {
    this.closed = true;
    this.cancelSourceRead('预览窗口已关闭');
    this.sourceWatchStop?.();
    this.sourceWatchStop = null;
    mwbReleaseRenderOwner(this.plugin, this.sourceWatchOwner);
    this.sourceWatchOwner = null;
    this.cancelPreview('预览窗口已关闭');
    this.renderController = null;
    this.renderBusy = false;
    this.cancelExport('预览窗口已关闭，导出已取消');
    ++this.generation;
    this.ready = false;
    this.clearPaginatedPreview();
    this.removeMeasurement();
    mwbReleaseRenderOwner(this.plugin, this.renderOwner);
    this.renderOwner = null;
    this.contentEl.empty();
  }
}

module.exports = class MathsemblePlugin extends Plugin {
  async onload() {
    if (this.manifest?.id && this.manifest.id !== 'mathsemble') {
      new Notice('Mathsemble 安装清单与代码不一致：请将同一版本的三个文件安装到 mathsemble 目录，然后重启。', 12000);
      throw new Error('Mathsemble plugin ID mismatch: expected mathsemble');
    }
    const assemblyService = mwbAssemblyService(this, {core:mwbAssemblyCore,
      compileMarkdown:mwbAssemblyMarkdown.compileMarkdown, parseYaml,
      previewFile:async file => {
        const scope=mwbSourceScope(file), snapshot=await mwbReadSourceSnapshot(this.app.vault,scope);
        new PreviewModal(this.app,this,file,snapshot.entries[0].record.markdown,null,
          {documentMode:true,sourceScope:scope,sourceSnapshot:snapshot}).open();
      }});
    const AssemblyView = mwbAssemblyView({ItemView,Component,Notice,core:mwbAssemblyCore,
      service:assemblyService,renderMarkdown:(markdown,container,path,owner) =>
        mwbRenderMarkdown(this.app,markdown,container,path,owner)});
    this.registerView('mathsemble-assembly', leaf => new AssemblyView(leaf,this));
    const openAssembly = async () => {
      let leaf=this.app.workspace.getLeavesOfType('mathsemble-assembly')[0];
      if (!leaf) { leaf=this.app.workspace.getLeaf('tab'); await leaf.setViewState({type:'mathsemble-assembly',active:true}); }
      await this.app.workspace.revealLeaf(leaf);
    };
    this.addCommand({id:'open-knowledge-assembly',name:'知识点与组题工作区',callback:openAssembly});
    this.addRibbonIcon('library','知识点与组题',()=>void openAssembly());
    this.addCommand({id:'set-current-line-question-heading',name:'将当前行设为五级块标题',
      editorCallback:(editor)=>{
        const cursor=editor.getCursor(),source=editor.getValue();
        const replacement=mwbQuestionHeadingEdit(source,cursor.line+1);
        if(!replacement){new Notice('请在顶层非空正文或标题行执行；代码、引用、注释和数学环境中的内容不会修改。');return;}
        editor.replaceRange(replacement,{line:cursor.line,ch:0},{line:cursor.line,ch:editor.getLine(cursor.line).length});
      }});
    this.addCommand({
      id:'diagnose-answer-visibility',
      name:'诊断当前题卡/讲义答案显隐（复制报告）',
      callback:async()=>{
        const view=this.app.workspace.getActiveViewOfType(MarkdownView);
        const file=view?.file;
        if(!file){new Notice('请先打开数学题卡或讲义');return;}
        const markdown=await this.app.vault.read(file);
        const fm=this.app.metadataCache.getFileCache(file)?.frontmatter || {};
        const root=view.containerEl;
        const live=!!root?.querySelector?.('.markdown-source-view.mod-cm6.is-live-preview');
        const reading=!!root?.querySelector?.('.markdown-preview-view');
        const slots=mathAnswerSlots(markdown);
        const report={
          插件:'Mathsemble',插件ID:this.manifest?.id || 'unknown',版本:'v'+(this.manifest?.version || 'unknown'),文件:file.path,
          是否识别为题卡:isQuestion(fm),
          讲义答案槽数量:answerSlots(markdown).length,
          题型:fm.question_type||fm.type||'未填写',
          当前模式:live?'实时预览':reading?'阅读视图':'源码模式或无法识别',
          视图已标记:!!root?.classList?.contains('mwb-question-note'),
          数学答案槽数量:slots.length,
          公式内部答案槽数量:answerSlots(markdown).filter(slot=>slot.inMath).length,
          公式内部答案槽说明:'A4 学生/教师导出支持；原生阅读视图与实时预览尚待宿主适配验收',
          数学答案槽位置:slots.map(s=>({from:s.from,to:s.to})),
          CodeMirror编辑器可访问:!!view.editor?.cm,
          源码模式显示答案属于正常行为:true,
        };
        try{
          await navigator.clipboard.writeText(JSON.stringify(report,null,2));
          new Notice('答案显隐诊断已复制到剪贴板');
        }catch(e){
          console.log('[Mathsemble] 答案显隐诊断',report);
          new Notice('无法复制诊断；报告已输出到开发者控制台');
        }
      }
    });
    this.addCommand({ id: 'preview-current-markdown-document', name: '长 Markdown 文档预览与 PDF 导出（实验）',
      callback: async () => {
        const file=this.app.workspace.getActiveViewOfType(MarkdownView)?.file;
        if (!file) {new Notice('请先打开 Markdown 文件');return;}
        try {
          const scope=mwbSourceScope(file), snapshot=await mwbReadSourceSnapshot(this.app.vault,scope);
          new PreviewModal(this.app,this,file,snapshot.entries[0].record.markdown,null,
            {documentMode:true,sourceScope:scope,sourceSnapshot:snapshot}).open();
        } catch(error) {new Notice('读取讲义失败：'+(error?.message || error),10000);}
      },
    });
    this.addCommand({ id: 'preview-current-question', name: '预览并导出当前数学题卡（P0）',
      callback: async () => {
        const view = this.app.workspace.getActiveViewOfType(MarkdownView);
        const file = view?.file;
        if (!file) { new Notice('请先打开一份 Markdown 题卡。'); return; }
        try {
          const scope=mwbSourceScope(file), snapshot=await mwbReadSourceSnapshot(this.app.vault,scope);
          new PreviewModal(this.app,this,file,snapshot.entries[0].record.markdown,null,
            {sourceScope:scope,sourceSnapshot:snapshot}).open();
        } catch(error) {new Notice('读取题卡失败：'+(error?.message || error),10000);}
      },
    });
    this.addCommand({ id: 'set-current-question-teaching-role', name: '设置当前题卡教学角色（例题/变式/训练）',
      callback: () => {
        const file = this.app.workspace.getActiveViewOfType(MarkdownView)?.file;
        if (!file) { new Notice('请先打开一份题卡'); return; }
        const fm = this.app.metadataCache.getFileCache(file)?.frontmatter;
        if (!isQuestion(fm)) { new Notice('当前文件没有可识别的试题类型或 object_type，已停止修改'); return; }
        new RolePickerModal(this.app, file).open();
      },
    });
    this.addCommand({ id: 'preview-current-folder-exam', name: '当前文件夹组卷并预览 A4 试卷',
      callback: async () => {
        try {
          const view = this.app.workspace.getActiveViewOfType(MarkdownView);
          const file = view?.file;
          if (!file) { new Notice('请先打开目标文件夹内的一道题卡。'); return; }
          const scope=mwbSourceScope(file,true), snapshot=await mwbReadSourceSnapshot(this.app.vault,scope);
          const records=snapshot.entries.map(entry=>entry.record);
          const exam = collectExamItems(records);
          if (!exam.items.length) { new Notice('当前文件夹未发现有效题卡（需有标准 type 或 object_type）。'); return; }
          if (exam.items.length > 100) throw new Error('一次组卷至多 100 道题，请拆分文件夹');
          const name = file.parent?.name || '根目录';
          new PreviewModal(this.app, this, file, '', {...exam, title:'数学试卷'},
            {sourceScope:scope,sourceSnapshot:snapshot}).open();
        } catch (e) { new Notice('文件夹组卷失败：'+(e?.message || e)); }
      },
    });
    // Markdown postprocessors run in Reading View, not CodeMirror Live Preview.
    // A processor root may not yet be connected to a reading view: annotate its
    // marks immediately rather than returning early based on element.closest().
    this.registerMarkdownPostProcessor((element, context) => {
      const fm = this.app.metadataCache.getCache(context.sourcePath)?.frontmatter;
      const question = isQuestion(fm);
      const mathMaterial = question || /^(?:handout|lesson|lecture|worksheet|讲义|试卷)$/i
        .test(String(fm?.note_type || '').trim());
      const reading = element.closest?.('.markdown-preview-view');
      // Typed answer markers come from the section's raw Markdown.
      // Native ==highlight== remains a regular Obsidian mark.
      const sectionSource = typeof context.getSectionInfo === 'function'
        ? context.getSectionInfo(element)?.text : null;
      const sectionHasAnswers = typeof sectionSource === 'string' &&
        (sectionSource.includes('?{') || sectionSource.includes('!{')) &&
        answerSlots(sectionSource).length > 0;
      if (reading) {
        reading.classList.toggle('mwb-reading-view', question);
        reading.classList.toggle('mwb-math-material', mathMaterial);
        const sizer = reading.querySelector('.markdown-preview-sizer') || element;
        sizer.classList.toggle('mwb-typography', question);
        if (sectionHasAnswers) {
          reading.parentElement?.classList.add('mwb-answer-note');
          reading.classList.add('mwb-answer-note');
        }
      }
      if (sectionHasAnswers) {
        void Promise.resolve(finishRenderMath()).then(() => {
          (element.ownerDocument?.defaultView || window).requestAnimationFrame(() => {
            if (!element.isConnected) return;
            mwbDecorateReadingTypedSlots(element, sectionSource);
          });
        }).catch(() => {});
      }
      if (reading && element.querySelector('ul, ol')) {
        void Promise.resolve(finishRenderMath()).then(() => {
          if (!element.isConnected) return;
          (element.ownerDocument?.defaultView || window).requestAnimationFrame(() => {
            if (!element.isConnected) return;
            try { layoutOptionGrids(element); }
            catch (e) { console.warn('[Mathsemble] reading option grid not ready:',e); }
          });
        }).catch(() => {});
      }
    });

    // Live Preview: replace *source ranges* ==$...$== with CodeMirror widgets.
    // This does not depend on Markdown highlight/MathJax DOM coincidence and
    // never modifies the user's Markdown or the PDF transformer.
    try {
      const cmRuntime = require('@codemirror/view'); // Obsidian's external CM6 runtime
      this.registerEditorExtension(createMathAnswerEditorExtension(
        cmRuntime, renderMath, finishRenderMath));
    } catch (e) {
      console.error('[Mathsemble] CodeMirror 6 答案隐藏扩展加载失败', e);
      new Notice('数学填空实时预览扩展未加载，请查看开发者控制台错误',10000);
    }
    const syncAnswerViews = () => {
      const leaves=this.app.workspace.getLeavesOfType?.('markdown') || [];
      syncQuestionViewClasses(leaves,
        file => this.app.metadataCache.getFileCache(file)?.frontmatter, isQuestion);
      // CodeMirror tracks edits and slot visibility itself. An empty dispatch
      // for every metadata update would repeatedly refresh all open editors.
    };
    if (typeof this.app.workspace.onLayoutReady === 'function')
      this.app.workspace.onLayoutReady(syncAnswerViews);
    else syncAnswerViews();
    const listen = (emitter, event) => {
      if (typeof emitter?.on === 'function' && typeof this.registerEvent === 'function')
        this.registerEvent(emitter.on(event, syncAnswerViews));
    };
    listen(this.app.workspace, 'file-open');
    listen(this.app.workspace, 'active-leaf-change');
    listen(this.app.workspace, 'layout-change');
    // Live Preview follows CodeMirror doc changes directly; refreshing every
    // editor-change would rescan the whole document and dispatch another update.
    listen(this.app.metadataCache, 'changed');
  }
};

